import sys
input = sys.stdin.read

def solve():
    data = input().split()
    b1 = int(data[0])
    q = int(data[1])
    l = int(data[2])
    m = int(data[3])
    bad_nums = set(int(data[i]) for i in range(4, 4 + m))

    if abs(b1) > l:
        print(0)
        return

    if b1 == 0:
        if 0 in bad_nums:
            print(0)
        else:
            print("inf")
        return

    if q == 0:
        count = 0
        if b1 not in bad_nums:
            count += 1
        if 0 not in bad_nums:
            print("inf")
        else:
            print(count)
        return

    if q == 1:
        if b1 not in bad_nums:
            print("inf")
        else:
            print(0)
        return

    if q == -1:
        if b1 not in bad_nums or -b1 not in bad_nums:
            print("inf")
        else:
            print(0)
        return

    count = 0
    current = b1
    while abs(current) <= l:
        if current not in bad_nums:
            count += 1
        current *= q
    print(count)

solve()

