import sys
input = sys.stdin.read
data = input().split()

b_1, q, l, m = map(int, data[:4])
bad_integers = set(map(int, data[4:]))

if abs(b_1) > l:
    print(0)
else:
    count = 0
    while abs(b_1) <= l:
        if b_1 not in bad_integers:
            count += 1
        if q == 1 and b_1 in bad_integers:
            break
        if q == 0:
            if b_1 in bad_integers:
                break
            else:
                if b_1 not in bad_integers:
                    count += 1
                break
        if count > 10**6:
            print("inf")
            break
        b_1 *= q
    print(count)

